/**
 * @name Eval Injection Analysis
 * @description Detects data flow from function parameters to eval() calls in licenses/__init__.py
 * @kind path-problem
 * @problem.severity error
 * @id py/eval-injection-analysis
 * @tags security
 *       external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EvalInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asCfgNode().(NameNode).getId() = "eval" and
      sink = call.getArg(0)
    )
  }
}

module EvalInjectionFlow = TaintTracking::Global<EvalInjectionConfig>;
import EvalInjectionFlow::PathGraph

from EvalInjectionFlow::PathNode source, EvalInjectionFlow::PathNode sink
where EvalInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential eval injection from $@.", source.getNode(), "parameter"

/**
 * @name Path traversal
 * @description Accessing paths influenced by users can allow arbitrary file access
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // For a library, we consider parameters of public functions as potential sources
    // or we can look for generic sources if we want to be broad.
    // Let's use a broad definition for now: any parameter.
    exists(DataFlow::ParameterNode p | source = p)
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "parameter"
